  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useEffect, useMemo, useRef, useState } from "react";
 19→import type { AgentStatus, ChatMessage, ClaudeMessage } from "@/lib/types";
 20→import { condenseMessages } from "@/lib/condense-messages";
 21→import { StatusBar } from "./status-bar";
 22→import { Message } from "./message";
 23→import { ControlRequest } from "./control-request";
 24→import { UserQuestion } from "./user-question";
 25→import { CondensedToolGroup } from "./condensed-tool-group";
 26→import { Button } from "@/components/ui/button";
 27→
 28→export function Chat({
 29→  connected,
 30→  status,
 31→  messages,
 32→  rawMessages,
 33→  onSendMessage,
 34→  onSpawnAgent,
 35→  onRespondToControl,
 36→  onRespondToUserQuestion,
 37→}: {
 38→  connected: boolean;
 39→  status: AgentStatus;
 40→  messages: ChatMessage[];
 41→  rawMessages: ClaudeMessage[];
 42→  onSendMessage: (content: string) => void;
 43→  onSpawnAgent: (prompt: string) => void;
 44→  onRespondToControl: (requestId: string, allow: boolean) => void;
 45→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 46→}) {
 47→  const [input, setInput] = useState("");
 48→  const [showRaw, setShowRaw] = useState(false);
 49→  const scrollRef = useRef<HTMLDivElement>(null);
 50→
 51→  useEffect(() => {
 52→    scrollRef.current?.scrollTo({
 53→      top: scrollRef.current.scrollHeight,
 54→      behavior: "smooth",
 55→    });
 56→  }, [messages, rawMessages, showRaw]);
 57→
 58→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 59→  const isActive = status === "connected" || status === "thinking";
 60→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 61→
 62→  function handleSubmit(e: React.FormEvent) {
 63→    e.preventDefault();
 64→    const trimmed = input.trim();
 65→    if (!trimmed) return;
 66→
 67→    if (isActive) {
 68→      onSendMessage(trimmed);
 69→    } else {
 70→      onSpawnAgent(trimmed);
 71→    }
 72→    setInput("");
 73→  }
 74→
 75→  return (
 76→    <div className="flex h-full flex-col">
 77→      <div className="relative">
 78→        <StatusBar connected={connected} status={status} />
 79→        <button
 80→          onClick={() => setShowRaw((v) => !v)}
 81→          className={`absolute right-3 top-1/2 -translate-y-1/2 rounded px-2 py-0.5 text-[10px] font-mono transition-colors ${
 82→            showRaw
 83→              ? "bg-foreground text-background"
 84→              : "bg-muted text-muted-foreground hover:bg-muted/80"
 85→          }`}
 86→        >
 87→          {showRaw ? "RAW" : "raw"}
 88→        </button>
 89→      </div>
 90→
 91→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-2">
 92→        {showRaw ? (
 93→          rawMessages.length === 0 ? (
 94→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
 95→              No raw messages yet
 96→            </div>
 97→          ) : (
 98→            <div className="space-y-1">
 99→              {rawMessages.map((msg, i) => (
100→                <RawMessage key={i} message={msg} index={i} />
101→              ))}
102→            </div>
103→          )
104→        ) : (
105→          <>
106→            {messages.length === 0 && (
107→              <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
108→                Type a prompt to spawn a Claude agent
109→              </div>
110→            )}
111→            {displayItems.map((item) => {
112→              if (item.kind === "condensed") {
113→                return <CondensedToolGroup key={item.id} group={item} />;
114→              }
115→              const msg = item.message;
116→              return msg.userQuestion ? (
117→                <UserQuestion
118→                  key={msg.id}
119→                  message={msg}
120→                  onRespond={onRespondToUserQuestion}
121→                />
122→              ) : msg.controlRequest ? (
123→                <ControlRequest
124→                  key={msg.id}
125→                  message={msg}
126→                  onRespond={onRespondToControl}
127→                />
128→              ) : (
129→                <Message key={msg.id} message={msg} />
130→              );
131→            })}
132→          </>
133→        )}
134→      </div>
135→
136→      {isArchived && messages.length > 0 ? (
137→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
138→          This session has ended
139→        </div>
140→      ) : (
141→        <form
142→          onSubmit={handleSubmit}
143→          className="flex gap-2 border-t px-4 py-3"
144→        >
145→          <input
146→            type="text"
147→            value={input}
148→            onChange={(e) => setInput(e.target.value)}
149→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
150→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
151→          />
152→          <Button type="submit" disabled={!connected || !input.trim()}>
153→            {isActive ? "Send" : "Spawn"}
154→          </Button>
155→        </form>
156→      )}
157→    </div>
158→  );
159→}
160→
161→/** Badge color per Claude NDJSON message type. */
162→const TYPE_COLORS: Record<string, string> = {
163→  system: "text-yellow-500",
164→  assistant: "text-blue-400",
165→  result: "text-green-500",
166→  control_request: "text-orange-400",
167→  keep_alive: "text-muted-foreground",
168→};
169→
170→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
171→  const [expanded, setExpanded] = useState(false);
172→  const subtype = (message as { subtype?: string }).subtype;
173→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
174→  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";
175→
176→  return (
177→    <div className="font-mono text-[11px] leading-relaxed">
178→      <button
179→        onClick={() => setExpanded((v) => !v)}
180→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
181→      >
182→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
183→        <span className={colorClass}>{typeLabel}</span>
184→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
185→      </button>
186→      {expanded && (
187→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
188→          {JSON.stringify(message, null, 2)}
189→        </pre>
190→      )}
191→    </div>
192→  );
193→}
