172→export function useWebSocket() {
173→  const wsRef = useRef<WebSocket | null>(null);
174→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
175→  const [connected, setConnected] = useState(false);
176→
177→  // Multi-agent state
178→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
179→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
180→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
181→
182→  // Per-agent deduplication: track count of processed messages per agent
183→  // to avoid duplicating messages already in local state during history replay.
184→  const processedCountRef = useRef<Map<string, number>>(new Map());
185→
186→  /** Immutably update a single agent's state in the Map. */
187→  const updateAgent = useCallback(
188→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
189→      setAgents((prev) => {
190→        const existing = prev.get(agentId);
191→        if (!existing) return prev;
192→        const next = new Map(prev);
193→        next.set(agentId, updater(existing));
194→        return next;
195→      });
196→    },
197→    []
198→  );
199→
200→  const connect = useCallback(() => {
201→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
202→    if (wsRef.current) {
203→      wsRef.current.close();
204→      wsRef.current = null;
205→    }
206→
207→    const ws = new WebSocket(WS_URL);
208→    wsRef.current = ws;
209→
210→    ws.onopen = () => setConnected(true);
211→
212→    ws.onclose = () => {
213→      setConnected(false);
214→      wsRef.current = null;
215→      // Reconnection guard: clear any existing timer before scheduling
216→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
217→      reconnectTimer.current = setTimeout(() => connect(), 2000);
218→    };
219→
220→    ws.onerror = () => {
221→      // onclose will fire after onerror, which triggers reconnect
222→    };
223→
224→    ws.onmessage = (event) => {
225→      let data: ServerMessage;
226→      try {
227→        data = JSON.parse(event.data as string);
228→      } catch {
229→        return;
230→      }
231→
232→      // ── message_history: replay full history from server ──
233→      if (data.type === "message_history") {
234→        const historyMsg = data as ServerMessageHistory;
235→        const agentId = historyMsg.agentId;
236→        const serverMessages = historyMsg.messages;
237→
238→        // Convert all server messages to ChatMessages + extract raw Claude messages
239→        const chatMessages: ChatMessage[] = [];
240→        const rawMessages: ClaudeMessage[] = [];
241→        for (const sm of serverMessages) {
242→          if (sm.type === "relay") {
243→            rawMessages.push(sm.message);
244→          }
245→          const cm = relayChatMessage(agentId, sm);
246→          if (cm) chatMessages.push(cm);
247→        }
248→
249→        // Skip messages already processed locally (dedup)
250→        const alreadyProcessed = processedCountRef.current.get(agentId) ?? 0;
251→        const newMessages = chatMessages.slice(alreadyProcessed);
252→
253→        if (newMessages.length > 0) {
254→          setAgents((prev) => {
255→            const existing = prev.get(agentId);
256→            if (!existing) {
257→              // Agent not yet in local state — create it
258→              const next = new Map(prev);
259→              next.set(agentId, {
260→                status: "idle",
261→                messages: chatMessages, // use full history for new agent
262→                rawMessages,
263→                label: "",
264→                tmuxSession: null,
265→                createdAt: 0,
266→              });
267→              return next;
268→            }
269→            // Replace messages with full server history (source of truth)
270→            const next = new Map(prev);
271→            next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
272→            return next;
273→          });
274→        }
275→
276→        processedCountRef.current.set(agentId, chatMessages.length);
277→        return;
278→      }
279→
280→      // ── history_cleared: wipe local messages for this agent ──
281→      if (data.type === "history_cleared") {
282→        updateAgent(data.agentId, (prev) => ({
283→          ...prev,
284→          messages: [],
285→          rawMessages: [],
286→        }));
287→        processedCountRef.current.set(data.agentId, 0);
288→        return;
289→      }
290→
291→      // ── cli_disconnected: show system message ──
292→      if (data.type === "cli_disconnected") {
293→        updateAgent(data.agentId, (prev) => ({
294→          ...prev,
295→          messages: [
296→            ...prev.messages,
297→            {
298→              id: nextId(),
299→              role: "system",
300→              content: "CLI session ended",
301→              timestamp: Date.now(),
302→            },
303→          ],
304→        }));
305→        return;
306→      }
307→
308→      // ── cli_connected: show system message ──
309→      if (data.type === "cli_connected") {
310→        updateAgent(data.agentId, (prev) => ({
311→          ...prev,
312→          messages: [
313→            ...prev.messages,
314→            {
315→              id: nextId(),
316→              role: "system",
317→              content: "CLI reconnected",
318→              timestamp: Date.now(),
319→            },
320→          ],
321→        }));
322→        return;
323→      }
324→
325→      // ── agent_list: reconcile sidebar state from server ──
326→      if (data.type === "agent_list") {
327→        const serverAgents = data.agents as AgentInfo[];
328→        setAgents((prev) => {
329→          const next = new Map(prev);
330→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
331→
332→          // Update or add agents from server
333→          for (const info of serverAgents) {
334→            const existing = next.get(info.agentId);
335→            if (existing) {
336→              next.set(info.agentId, {
337→                ...existing,
338→                status: info.status,
339→                tmuxSession: info.tmuxSession,
340→                label: info.label,
341→              });
342→            } else {
343→              next.set(info.agentId, {
344→                status: info.status,
345→                messages: [],
346→                rawMessages: [],
347→                label: info.label,
348→                tmuxSession: info.tmuxSession,
349→                createdAt: info.createdAt,
350→              });
351→            }
352→          }
353→
354→          // Remove agents no longer on the server
355→          for (const id of next.keys()) {
356→            if (!serverIds.has(id)) {
357→              next.delete(id);
358→            }
359→          }
360→
361→          return next;
362→        });
363→        setAgentOrder(serverAgents.map((a) => a.agentId));
364→        return;
365→      }
366→
367→      // ── spawned: auto-select the newly created agent ──
368→      if (data.type === "spawned") {
369→        setActiveAgentId(data.agentId);
370→        return;
371→      }
372→
373→      // ── status: update a specific agent's status ──
374→      if (data.type === "status") {
375→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
376→        return;
377→      }
378→
379→      // ── error: append to agent's message list ──
380→      if (data.type === "error") {
381→        updateAgent(data.agentId, (prev) => ({
382→          ...prev,
383→          messages: [
384→            ...prev.messages,
385→            {
386→              id: nextId(),
387→              role: "system",
388→              content: `Error: ${data.error}`,
389→              timestamp: Date.now(),
390→            },
391→          ],
392→        }));
393→        // Track processed count for dedup
394→        processedCountRef.current.set(
395→          data.agentId,
396→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
397→        );
398→        return;
399→      }
400→
401→      // ── relay: append claude message to agent's history ──
402→      if (data.type === "relay") {
403→        const agentId = data.agentId;
404→        const rawMsg = data.message;
405→        const chatMsg = relayChatMessage(agentId, data);
406→
407→        updateAgent(agentId, (prev) => ({
408→          ...prev,
409→          rawMessages: [...prev.rawMessages, rawMsg],
410→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
411→        }));
412→        if (chatMsg) {
413→          // Track processed count for dedup
414→          processedCountRef.current.set(
415→            agentId,
416→            (processedCountRef.current.get(agentId) ?? 0) + 1
417→          );
418→        }
419→        return;
420→      }
421→    };
422→  }, [updateAgent]);
423→
424→  useEffect(() => {
425→    connect();
426→    return () => {
427→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
428→      wsRef.current?.close();
429→    };
430→  }, [connect]);
431→
432→  const send = useCallback((data: object) => {
433→    if (wsRef.current?.readyState === WebSocket.OPEN) {
434→      wsRef.current.send(JSON.stringify(data));
435→    }
436→  }, []);
437→
438→  const spawnAgent = useCallback(
439→    (prompt: string) => {
440→      send({ type: "spawn", prompt });
441→    },
442→    [send]
443→  );
444→
445→  const sendMessage = useCallback(
446→    (content: string) => {
447→      if (!activeAgentId) return;
448→      // Optimistically add user message to local state
449→      updateAgent(activeAgentId, (prev) => ({
450→        ...prev,
451→        messages: [
452→          ...prev.messages,
453→          {
454→            id: nextId(),
455→            role: "user",
456→            content,
457→            timestamp: Date.now(),
458→          },
459→        ],
460→      }));
461→      send({ type: "send_message", agentId: activeAgentId, content });
462→    },
463→    [send, activeAgentId, updateAgent]
464→  );
465→
466→  const respondToControl = useCallback(
467→    (requestId: string, allow: boolean) => {
468→      if (!activeAgentId) return;
469→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
470→      updateAgent(activeAgentId, (prev) => ({
471→        ...prev,
472→        messages: prev.messages.map((m) =>
473→          m.controlRequest?.id === requestId
474→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
475→            : m
476→        ),
477→      }));
478→    },
479→    [send, activeAgentId, updateAgent]
480→  );
481→
482→  /** Respond to an AskUserQuestion control request with the user's selections. */
483→  const respondToUserQuestion = useCallback(
484→    (requestId: string, answers: Record<string, string>) => {
485→      if (!activeAgentId) return;
486→      send({
487→        type: "control_response",
488→        agentId: activeAgentId,
489→        request_id: requestId,
490→        allow: true,
491→        answers,
492→      });
493→      updateAgent(activeAgentId, (prev) => ({
494→        ...prev,
495→        messages: prev.messages.map((m) =>
496→          m.userQuestion?.requestId === requestId
497→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
498→            : m
499→        ),
500→      }));
501→    },
502→    [send, activeAgentId, updateAgent]
503→  );
504→
505→  // ── Agent management actions ──────────────────────────────────────────────
506→
507→  const killAgent = useCallback(
508→    (agentId: string) => {
509→      send({ type: "kill_agent", agentId });
510→    },
511→    [send]
512→  );
513→
514→  const deleteAgent = useCallback(
515→    (agentId: string) => {
516→      send({ type: "delete_agent", agentId });
517→      // Deselect if we just deleted the active agent
518→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
519→    },
520→    [send]
521→  );
522→
523→  const renameAgent = useCallback(
524→    (agentId: string, label: string) => {
525→      send({ type: "rename_agent", agentId, label });
526→    },
527→    [send]
528→  );
529→
530→  const clearHistory = useCallback(
531→    (agentId: string) => {
532→      send({ type: "clear_history", agentId });
533→    },
534→    [send]
535→  );
536→
537→  // Derived values for the active agent
538→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
539→  const activeStatus = useMemo<AgentStatus>(
540→    () => activeAgent?.status ?? "idle",
541→    [activeAgent?.status]
542→  );
543→  const activeMessages = useMemo<ChatMessage[]>(
544→    () => activeAgent?.messages ?? [],
545→    [activeAgent?.messages]
546→  );
547→  const activeRawMessages = useMemo<ClaudeMessage[]>(
548→    () => activeAgent?.rawMessages ?? [],
549→    [activeAgent?.rawMessages]
550→  );
551→
552→  return {
553→    connected,
554→    agents,
555→    agentOrder,
556→    activeAgentId,
557→    setActiveAgentId,
558→    activeStatus,
559→    activeMessages,
560→    activeRawMessages,
561→    spawnAgent,
562→    sendMessage,
563→    respondToControl,
564→    respondToUserQuestion,
565→    killAgent,
566→    deleteAgent,
567→    renameAgent,
568→    clearHistory,
569→  };
570→}
