  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Resilience features
 18→ *
 19→ * - **Server-side message history** — every relay message is stored per-agent.
 20→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 21→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 22→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 23→ *   can reconnect to the new server if they retry their WebSocket connection.
 24→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 25→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 26→ *
 27→ * ## Message flow
 28→ *
 29→ * 1. Browser sends `{ type: "spawn", prompt }`.
 30→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 31→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
 32→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
 33→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 34→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 35→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 36→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 37→ */
 38→import { WebSocketServer, WebSocket } from "ws";
 39→import { execSync, spawn } from "child_process";
 40→import { randomBytes } from "crypto";
 41→import type { IncomingMessage } from "http";
 42→import type {
 43→  BrowserMessage,
 44→  ClaudeMessage,
 45→  ServerMessage,
 46→  AgentStatus,
 47→  AgentInfo,
 48→} from "../lib/types";
 49→import { SessionStore, type PersistedAgent } from "./session-store";
 50→
 51→const PORT = 9900;
 52→const TMUX_SESSION_PREFIX = "thos-agent";
 53→const wss = new WebSocketServer({ port: PORT });
 54→const store = new SessionStore();
 55→
 56→// ── Multi-agent state ──────────────────────────────────────────────────────
 57→
 58→interface AgentState {
 59→  agentId: string;
 60→  claudeSocket: WebSocket | null;
 61→  tmuxSession: string | null;
 62→  pendingPrompt: string | null;
 63→  status: AgentStatus;
 64→  label: string;
 65→  createdAt: number;
 66→  /** Captured from system/init, used in subsequent user messages. */
 67→  sessionId: string | null;
 68→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
 69→  pendingControlRequests: Map<string, Record<string, unknown>>;
 70→  /** All messages sent to the browser for this agent (source of truth). */
 71→  messageHistory: ServerMessage[];
 72→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
 73→  pendingMessages: string[];
 74→}
 75→
 76→const agents = new Map<string, AgentState>();
 77→
 78→/** All active browser connections (supports multiple tabs). */
 79→const browserSockets = new Set<WebSocket>();
 80→
 81→/** Generate a short random agent ID. */
 82→function newAgentId(): string {
 83→  return randomBytes(4).toString("hex");
 84→}
 85→
 86→// ── tmux helpers ───────────────────────────────────────────────────────────
 87→
 88→/** Return the set of currently alive tmux session names matching the thos prefix. */
 89→function listAliveTmuxSessions(): Set<string> {
 90→  try {
 91→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
 92→      encoding: "utf-8",
 93→    }).trim();
 94→    if (!output) return new Set();
 95→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
 96→  } catch {
 97→    return new Set();
 98→  }
 99→}
100→
101→// ── Persistence helpers ────────────────────────────────────────────────────
102→
103→/** Build a PersistedAgent snapshot from live state. */
104→function toPersistedAgent(agent: AgentState): PersistedAgent {
105→  return {
106→    id: agent.agentId,
107→    state: {
108→      agentId: agent.agentId,
109→      status: agent.status,
110→      tmuxSession: agent.tmuxSession,
111→      label: agent.label,
112→      createdAt: agent.createdAt,
113→      sessionId: agent.sessionId,
114→    },
115→    messageHistory: agent.messageHistory,
116→  };
117→}
118→
119→/** Persist agent state (debounced — use for streaming events). */
120→function persistAgent(agent: AgentState) {
121→  store.save(toPersistedAgent(agent));
122→}
123→
124→/** Persist agent state immediately (use for critical state changes). */
125→function persistAgentSync(agent: AgentState) {
126→  store.saveSync(toPersistedAgent(agent));
127→}
128→
129→// ── Restore from disk on startup ───────────────────────────────────────────
130→
131→function restoreAgents() {
132→  const persisted = store.loadAll();
133→  const aliveSessions = listAliveTmuxSessions();
134→
135→  for (const p of persisted) {
136→    const agent: AgentState = {
137→      agentId: p.state.agentId,
138→      claudeSocket: null,
139→      tmuxSession: p.state.tmuxSession,
140→      pendingPrompt: null,
141→      status: p.state.status,
142→      label: p.state.label,
143→      createdAt: p.state.createdAt,
144→      sessionId: p.state.sessionId,
145→      pendingControlRequests: new Map(),
146→      messageHistory: p.messageHistory,
147→      pendingMessages: [],
148→    };
149→
150→    // Determine status for agents that were active when the server last ran
151→    if (agent.status !== "done" && agent.status !== "error") {
152→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
153→      if (tmuxAlive) {
154→        // tmux session still alive — CLI may reconnect to this server
155→        agent.status = "disconnected";
156→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
157→      } else {
158→        // tmux session gone — agent is archived
159→        agent.status = "done";
160→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
161→      }
162→    }
163→
164→    agents.set(agent.agentId, agent);
165→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${agent.messageHistory.length} messages)`);
166→  }
167→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
168→}
169→
170→restoreAgents();
171→
172→// ── Helpers ────────────────────────────────────────────────────────────────
173→
174→/** Send a JSON message to all connected browsers. */
175→function sendToBrowser(msg: ServerMessage) {
176→  const payload = JSON.stringify(msg);
177→  for (const ws of browserSockets) {
178→    if (ws.readyState === WebSocket.OPEN) {
179→      ws.send(payload);
180→    }
181→  }
182→}
183→
184→/** Build a snapshot of all agents for the sidebar. */
185→function buildAgentList(): AgentInfo[] {
186→  return Array.from(agents.values()).map((a) => ({
187→    agentId: a.agentId,
188→    status: a.status,
189→    tmuxSession: a.tmuxSession,
190→    label: a.label,
191→    createdAt: a.createdAt,
192→  }));
193→}
194→
195→/** Send the full agent list to all browsers. */
196→function broadcastAgentList() {
197→  sendToBrowser({ type: "agent_list", agents: buildAgentList() });
198→}
199→
200→/** Update an agent's status, notify browsers, broadcast list, and persist. */
201→function setAgentStatus(agentId: string, status: AgentStatus) {
202→  const agent = agents.get(agentId);
203→  if (!agent) return;
204→  agent.status = status;
205→  sendToBrowser({ type: "status", agentId, status });
206→  broadcastAgentList();
207→  persistAgentSync(agent);
208→}
209→
210→/**
211→ * Record a message in the agent's history and send to all browsers.
212→ * This is used for relay messages so that message history is the source of truth.
213→ */
214→function recordAndSend(agentId: string, msg: ServerMessage) {
215→  const agent = agents.get(agentId);
216→  if (agent) {
217→    agent.messageHistory.push(msg);
218→    persistAgent(agent); // debounced — streaming messages come fast
219→  }
220→  sendToBrowser(msg);
221→}
222→
223→// ── Agent lifecycle ────────────────────────────────────────────────────────
224→
225→/**
226→ * Stop a running agent by killing its tmux session and closing the CLI socket.
227→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
228→ */
229→function stopAgent(agentId: string) {
230→  const agent = agents.get(agentId);
231→  if (!agent) return;
232→
233→  if (agent.tmuxSession) {
234→    try {
235→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
236→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
237→    } catch {
238→      // Session may already be dead
239→    }
240→  }
241→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
242→    agent.claudeSocket.close();
243→  }
244→  agent.claudeSocket = null;
245→  setAgentStatus(agentId, "done");
246→}
247→
248→/**
249→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
250→ */
251→function deleteAgent(agentId: string) {
252→  const agent = agents.get(agentId);
253→  if (!agent) return;
254→
255→  if (agent.tmuxSession) {
256→    try {
257→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
258→    } catch {}
259→  }
260→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
261→    agent.claudeSocket.close();
262→  }
263→  agents.delete(agentId);
264→  store.remove(agentId);
265→  broadcastAgentList();
266→}
267→
268→/**
269→ * Spawn a new Claude CLI process inside a tmux session.
270→ *
271→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
272→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
273→ */
274→function spawnClaude(prompt: string): string {
275→  const agentId = newAgentId();
276→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
277→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
278→
279→  const agent: AgentState = {
280→    agentId,
281→    claudeSocket: null,
282→    tmuxSession: null,
283→    pendingPrompt: prompt,
284→    status: "spawning",
285→    label,
286→    createdAt: Date.now(),
287→    sessionId: null,
288→    pendingControlRequests: new Map(),
289→    messageHistory: [],
290→    pendingMessages: [],
291→  };
292→  agents.set(agentId, agent);
293→
294→  // Notify browsers
295→  sendToBrowser({ type: "spawned", agentId });
296→  broadcastAgentList();
297→  persistAgentSync(agent);
298→
299→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
300→  // tmux new-session runs detached (-d) so spawn() returns immediately.
301→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
302→
303→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
304→    stdio: "ignore",
305→  });
306→
307→  tmux.on("error", (err) => {
308→    console.error("[tmux spawn error]", err);
309→    setAgentStatus(agentId, "error");
310→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
311→  });
312→
313→  tmux.on("exit", (code) => {
314→    if (code !== 0) {
315→      console.error(`[tmux] new-session exited with code ${code}`);
316→      setAgentStatus(agentId, "error");
317→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
318→      return;
319→    }
320→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
321→    agent.tmuxSession = sessionName;
322→    broadcastAgentList();
323→    persistAgentSync(agent);
324→  });
325→
326→  return agentId;
327→}
328→
329→// ── Message handlers ───────────────────────────────────────────────────────
330→
331→/**
332→ * Process an incoming NDJSON message from a specific Claude CLI.
333→ *
334→ * Status flow matches the Companion protocol:
335→ * - hook_response → send pending prompt → "thinking"
336→ * - system/init   → "connected" + capture session_id
337→ * - assistant      → "thinking"
338→ * - result         → "connected" (CLI stays alive for multi-turn)
339→ * - CLI disconnect → "done" (handled in connection close handler)
340→ */
341→function handleClaudeMessage(agentId: string, raw: string) {
342→  const agent = agents.get(agentId);
343→  if (!agent) return;
344→
345→  let msg: ClaudeMessage;
346→  try {
347→    msg = JSON.parse(raw);
348→  } catch {
349→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
350→    return;
351→  }
352→
353→  // Silently ignore keep_alive messages
354→  if (msg.type === "keep_alive") return;
355→
356→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
357→
358→  // After hook_response, send the pending prompt
359→  if (
360→    msg.type === "system" &&
361→    (msg as { subtype?: string }).subtype === "hook_response" &&
362→    agent.pendingPrompt &&
363→    agent.claudeSocket?.readyState === WebSocket.OPEN
364→  ) {
365→    const userMsg = JSON.stringify({
366→      type: "user",
367→      message: { role: "user", content: agent.pendingPrompt },
368→      parent_tool_use_id: null,
369→      session_id: agent.sessionId ?? "",
370→    });
371→    console.log(`[server → claude:${agentId}]`, userMsg);
372→    agent.claudeSocket.send(userMsg + "\n");
373→    agent.pendingPrompt = null;
374→    setAgentStatus(agentId, "thinking");
375→  }
376→
377→  // Track status based on message type
378→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
379→    // Capture session_id for subsequent user messages
380→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
381→    setAgentStatus(agentId, "connected");
382→  } else if (msg.type === "assistant") {
383→    setAgentStatus(agentId, "thinking");
384→  } else if (msg.type === "result") {
385→    // CLI stays alive after result — ready for the next turn.
386→    // Status only goes to "done" when the CLI WebSocket actually closes.
387→    setAgentStatus(agentId, "connected");
388→  }
389→
390→  // Store control_request inputs for building proper responses later
391→  if (msg.type === "control_request") {
392→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
393→    if (cr.request_id && cr.request?.input) {
394→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
395→    }
396→  }
397→
398→  // Record in history and relay to browsers
399→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
400→}
401→
402→/**
403→ * Process an incoming JSON message from the browser.
404→ * - `spawn`: create a new agent (does NOT kill others).
405→ * - `send_message`: forward a follow-up user message to the specified agent.
406→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
407→ * - `kill_agent`: stop the CLI and tmux session.
408→ * - `delete_agent`: permanently remove an agent.
409→ * - `rename_agent`: update an agent's label.
410→ * - `clear_history`: wipe an agent's message history.
411→ */
412→function handleBrowserMessage(raw: string) {
413→  let msg: BrowserMessage;
414→  try {
415→    msg = JSON.parse(raw);
416→  } catch {
417→    console.error("[browser] invalid JSON:", raw);
418→    return;
419→  }
420→
421→  console.log("[browser →]", msg.type);
422→
423→  switch (msg.type) {
424→    case "spawn":
425→      spawnClaude(msg.prompt);
426→      break;
427→
428→    case "send_message": {
429→      const agent = agents.get(msg.agentId);
430→      if (!agent) {
431→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
432→        break;
433→      }
434→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
435→        const userMsg = JSON.stringify({
436→          type: "user",
437→          message: { role: "user", content: msg.content },
438→          parent_tool_use_id: null,
439→          session_id: agent.sessionId ?? "",
440→        });
441→        agent.claudeSocket.send(userMsg + "\n");
442→        setAgentStatus(msg.agentId, "thinking");
443→      } else {
444→        // Queue message for delivery when CLI reconnects
445→        const userMsg = JSON.stringify({
446→          type: "user",
447→          message: { role: "user", content: msg.content },
448→          parent_tool_use_id: null,
449→          session_id: agent.sessionId ?? "",
450→        });
451→        agent.pendingMessages.push(userMsg);
452→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
453→        persistAgentSync(agent);
454→      }
455→      break;
456→    }
457→
458→    case "control_response": {
459→      const agent = agents.get(msg.agentId);
460→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
461→        // Retrieve the original tool input to include as updatedInput (required by protocol)
462→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
463→        agent.pendingControlRequests.delete(msg.request_id);
464→
465→        // If the browser sent answers (from AskUserQuestion), merge them into the input
466→        const answers = (msg as { answers?: Record<string, string> }).answers;
467→        const updatedInput = answers
468→          ? { ...originalInput, answers }
469→          : originalInput;
470→
471→        const response = JSON.stringify({
472→          type: "control_response",
473→          response: {
474→            subtype: "success",
475→            request_id: msg.request_id,
476→            response: msg.allow
477→              ? { behavior: "allow", updatedInput }
478→              : { behavior: "deny", message: "Denied by user" },
479→          },
480→        });
481→        agent.claudeSocket.send(response + "\n");
482→      }
483→      break;
484→    }
485→
486→    case "kill_agent":
487→      stopAgent(msg.agentId);
488→      break;
489→
490→    case "delete_agent":
491→      deleteAgent(msg.agentId);
492→      break;
493→
494→    case "rename_agent": {
495→      const agent = agents.get(msg.agentId);
496→      if (!agent) break;
497→      agent.label = msg.label;
498→      broadcastAgentList();
499→      persistAgentSync(agent);
500→      break;
501→    }
502→
503→    case "clear_history": {
504→      const agent = agents.get(msg.agentId);
505→      if (!agent) break;
506→      agent.messageHistory = [];
507→      persistAgentSync(agent);
508→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
509→      break;
510→    }
511→  }
512→}
513→
514→// ── Send message history to a single browser socket ────────────────────────
515→
516→/** Send full state to a newly connected browser: agent list + message history per agent. */
517→function sendFullStateToSocket(ws: WebSocket) {
518→  if (ws.readyState !== WebSocket.OPEN) return;
519→
520→  // 1. Agent list
521→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList() }));
522→
523→  // 2. Message history per agent
524→  for (const agent of agents.values()) {
525→    if (agent.messageHistory.length > 0) {
526→      ws.send(
527→        JSON.stringify({
528→          type: "message_history",
529→          agentId: agent.agentId,
530→          messages: agent.messageHistory,
531→        })
532→      );
533→    }
534→  }
535→}
536→
537→// ── Connection handler — route by URL path ────────────────────────────────
538→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
539→  const path = req.url ?? "/";
540→  console.log(`[ws connected] path=${path}`);
541→
542→  if (path === "/browser") {
543→    browserSockets.add(ws);
544→
545→    // Send full state to this browser
546→    sendFullStateToSocket(ws);
547→
548→    ws.on("message", (data) => {
549→      handleBrowserMessage(data.toString());
550→    });
551→
552→    ws.on("close", () => {
553→      console.log("[browser disconnected]");
554→      browserSockets.delete(ws);
555→      // Do NOT kill agents — keep them alive for reconnect
556→    });
557→  } else if (path.startsWith("/claude/")) {
558→    // Parse agentId from /claude/<agentId>
559→    const agentId = path.slice("/claude/".length);
560→    const agent = agents.get(agentId);
561→
562→    if (!agent) {
563→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
564→      ws.close();
565→      return;
566→    }
567→
568→    agent.claudeSocket = ws;
569→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
570→
571→    // Notify browsers that CLI is connected
572→    sendToBrowser({ type: "cli_connected", agentId });
573→
574→    // Flush any pending messages queued while CLI was disconnected
575→    if (agent.pendingMessages.length > 0) {
576→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
577→      for (const queued of agent.pendingMessages) {
578→        ws.send(queued + "\n");
579→      }
580→      agent.pendingMessages = [];
581→      persistAgentSync(agent);
582→    }
583→
584→    ws.on("message", (data) => {
585→      handleClaudeMessage(agentId, data.toString());
586→    });
587→
588→    ws.on("close", () => {
589→      console.log(`[claude:${agentId} CLI disconnected]`);
590→      if (agent.claudeSocket === ws) {
591→        agent.claudeSocket = null;
592→        if (agent.status !== "error") {
593→          setAgentStatus(agentId, "done");
594→          sendToBrowser({ type: "cli_disconnected", agentId });
595→        }
596→      }
597→    });
598→  } else {
599→    console.log(`[ws] unknown path: ${path}, closing`);
600→    ws.close();
601→  }
602→});
603→
604→// ── Graceful shutdown ─────────────────────────────────────────────────────
605→
606→function shutdown() {
607→  console.log("[ws server] shutting down...");
608→
609→  // Persist all agents synchronously before exit — do NOT kill tmux sessions
610→  // so CLI processes can reconnect if the server restarts.
611→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
612→  store.flushAll(allPersisted);
613→  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);
614→
615→  wss.close();
616→  process.exit(0);
617→}
618→
619→process.on("SIGTERM", shutdown);
620→process.on("SIGINT", shutdown);
621→
622→console.log(`[ws server] listening on port ${PORT}`);
