  3→/**
  4→ * Renders an AskUserQuestion control request as an interactive question card.
  5→ *
  6→ * Each question shows its options as clickable chips. For single-select
  7→ * questions, clicking an option selects it (deselects others). For
  8→ * multi-select, clicking toggles the option. A "Submit" button sends the
  9→ * answers back to Claude via the control_response flow.
 10→ */
 11→
 12→import { useState } from "react";
 13→import { Button } from "@/components/ui/button";
 14→import type { ChatMessage } from "@/lib/types";
 15→import { cn } from "@/lib/utils";
 16→
 17→export function UserQuestion({
 18→  message,
 19→  onRespond,
 20→}: {
 21→  message: ChatMessage;
 22→  onRespond: (requestId: string, answers: Record<string, string>) => void;
 23→}) {
 24→  const uq = message.userQuestion;
 25→  if (!uq) return null;
 26→
 27→  return (
 28→    <div className="mx-auto w-full max-w-lg space-y-4 rounded-lg border-2 border-dashed border-muted-foreground/30 p-4">
 29→      {uq.questions.map((q, i) => (
 30→        <QuestionBlock
 31→          key={i}
 32→          question={q.question}
 33→          header={q.header}
 34→          options={q.options}
 35→          multiSelect={q.multiSelect}
 36→          resolved={uq.resolved}
 37→          onSubmit={(answer) => {
 38→            // Build the answers object keyed by question index
 39→            // For now each question submits independently — could batch if needed
 40→            const answers: Record<string, string> = { [`q${i}`]: answer };
 41→            onRespond(uq.requestId, answers);
 42→          }}
 43→        />
 44→      ))}
 45→    </div>
 46→  );
 47→}
 48→
 49→function QuestionBlock({
 50→  question,
 51→  header,
 52→  options,
 53→  multiSelect,
 54→  resolved,
 55→  onSubmit,
 56→}: {
 57→  question: string;
 58→  header?: string;
 59→  options: { label: string; description?: string }[];
 60→  multiSelect: boolean;
 61→  resolved?: boolean;
 62→  onSubmit: (answer: string) => void;
 63→}) {
 64→  const [selected, setSelected] = useState<Set<number>>(new Set());
 65→
 66→  function toggle(idx: number) {
 67→    if (resolved) return;
 68→    setSelected((prev) => {
 69→      const next = new Set(prev);
 70→      if (multiSelect) {
 71→        if (next.has(idx)) next.delete(idx);
 72→        else next.add(idx);
 73→      } else {
 74→        if (next.has(idx)) next.clear();
 75→        else {
 76→          next.clear();
 77→          next.add(idx);
 78→        }
 79→      }
 80→      return next;
 81→    });
 82→  }
 83→
 84→  function handleSubmit() {
 85→    const labels = options
 86→      .filter((_, i) => selected.has(i))
 87→      .map((o) => o.label);
 88→    onSubmit(labels.join(", "));
 89→  }
 90→
 91→  return (
 92→    <div>
 93→      {header && (
 94→        <div className="mb-1 text-xs font-semibold text-muted-foreground">
 95→          {header}
 96→        </div>
 97→      )}
 98→      <div className="mb-3 text-sm">{question}</div>
 99→      <div className="mb-3 flex flex-wrap gap-2">
100→        {options.map((opt, i) => (
101→          <button
102→            key={i}
103→            type="button"
104→            disabled={!!resolved}
105→            onClick={() => toggle(i)}
106→            className={cn(
107→              "rounded-md border px-3 py-1.5 text-xs transition-colors",
108→              selected.has(i)
109→                ? "border-primary bg-primary text-primary-foreground"
110→                : "border-muted-foreground/30 bg-secondary hover:border-primary/50",
111→              resolved && "opacity-60 cursor-default"
112→            )}
113→            title={opt.description}
114→          >
115→            {opt.label}
116→            {opt.description && (
117→              <span className="ml-1 text-[10px] opacity-70">
118→                — {opt.description}
119→              </span>
120→            )}
121→          </button>
122→        ))}
123→      </div>
124→      {!resolved ? (
125→        <Button
126→          size="sm"
127→          disabled={selected.size === 0}
128→          onClick={handleSubmit}
129→        >
130→          Submit
131→        </Button>
132→      ) : (
133→        <div className="text-xs italic text-muted-foreground">Answered</div>
134→      )}
135→    </div>
136→  );
137→}
