 29→}: TaskPanelProps) {
 30→  const [showCreate, setShowCreate] = useState(false);
 31→  const [showDone, setShowDone] = useState(false);
 32→
 33→  const grouped = useMemo(() => {
 34→    const inProgress = tasks.filter((t) => t.status === "in-progress");
 35→    const todo = tasks.filter((t) => t.status === "todo");
 36→    const done = tasks.filter((t) => t.status === "done");
 37→    return { inProgress, todo, done };
 38→  }, [tasks]);
 39→
 40→  return (
 41→    <div className="flex h-full flex-col">
 42→      {/* Header */}
 43→      <div className="flex items-center justify-between border-b px-3 py-2">
 44→        <span className="text-xs font-semibold">Tasks</span>
 45→        <div className="flex items-center gap-1">
 46→          <Button
 47→            variant="ghost"
 48→            size="icon-xs"
 49→            onClick={() => setShowCreate((v) => !v)}
 50→            title="New task"
 51→          >
 52→            <Plus className="size-3.5" />
 53→          </Button>
 54→          <Button variant="ghost" size="icon-xs" onClick={onClose} title="Close panel">
 55→            <X className="size-3.5" />
 56→          </Button>
 57→        </div>
 58→      </div>
 59→
 60→      {/* Create form */}
 61→      {showCreate && (
 62→        <TaskCreateForm
 63→          onCreate={(title, description, priority) => {
 64→            onCreateTask(title, description, priority);
 65→            setShowCreate(false);
 66→          }}
 67→        />
 68→      )}
 69→
 70→      {/* Task list */}
 71→      <div className="flex-1 overflow-y-auto">
 72→        {tasks.length === 0 && !showCreate && (
 73→          <div className="flex h-32 items-center justify-center text-xs text-muted-foreground">
 74→            No tasks yet
 75→          </div>
 76→        )}
 77→
 78→        {/* In Progress */}
 79→        {grouped.inProgress.length > 0 && (
 80→          <TaskGroup label="In Progress" count={grouped.inProgress.length}>
 81→            {grouped.inProgress.map((task) => (
 82→              <TaskCard
 83→                key={task.id}
 84→                task={task}
 85→                onUpdate={onUpdateTask}
 86→                onDelete={onDeleteTask}
 87→                onDelegate={onDelegateTask}
 88→                onSelectAgent={onSelectAgent}
 89→              />
 90→            ))}
 91→          </TaskGroup>
 92→        )}
 93→
 94→        {/* Todo */}
 95→        {grouped.todo.length > 0 && (
 96→          <TaskGroup label="Todo" count={grouped.todo.length}>
 97→            {grouped.todo.map((task) => (
 98→              <TaskCard
 99→                key={task.id}
100→                task={task}
101→                onUpdate={onUpdateTask}
102→                onDelete={onDeleteTask}
103→                onDelegate={onDelegateTask}
104→                onSelectAgent={onSelectAgent}
105→              />
106→            ))}
107→          </TaskGroup>
108→        )}
109→
110→        {/* Done (collapsible) */}
111→        {grouped.done.length > 0 && (
112→          <div className="border-t">
113→            <button
114→              className="flex w-full items-center justify-between px-3 py-2 text-xs text-muted-foreground hover:text-foreground transition-colors"
115→              onClick={() => setShowDone((v) => !v)}
116→            >
117→              <span className="font-semibold">Done ({grouped.done.length})</span>
118→              <ChevronDown
119→                className={cn("size-3 transition-transform", showDone && "rotate-180")}
120→              />
121→            </button>
122→            {showDone && (
123→              <div className="space-y-2 px-3 pb-3">
124→                {grouped.done.map((task) => (
125→                  <TaskCard
126→                    key={task.id}
127→                    task={task}
128→                    onUpdate={onUpdateTask}
129→                    onDelete={onDeleteTask}
130→                    onDelegate={onDelegateTask}
131→                    onSelectAgent={onSelectAgent}
132→                  />
133→                ))}
134→              </div>
135→            )}
136→          </div>
137→        )}
138→      </div>
139→    </div>
140→  );
141→}
