 73→              onKeyDown={(e) => {
 74→                if (e.key === "Enter") handleSaveEdit();
 75→                if (e.key === "Escape") handleCancelEdit();
 76→              }}
 77→              autoFocus
 78→            />
 79→          ) : (
 80→            <span
 81→              className={cn(
 82→                "truncate font-medium cursor-pointer",
 83→                task.status === "done" && "line-through text-muted-foreground"
 84→              )}
 85→              onDoubleClick={() => setEditing(true)}
 86→            >
 87→              {task.title}
 88→            </span>
 89→          )}
 90→        </div>
 91→        <div className="flex shrink-0 items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
 92→          {!task.agentId && task.status !== "done" && (
 93→            <Button
 94→              variant="ghost"
 95→              size="icon-xs"
 96→              onClick={() => onDelegate(task.id)}
 97→              title="Delegate to agent"
 98→            >
 99→              <Play className="size-3" />
100→            </Button>
101→          )}
102→          <Button
103→            variant="ghost"
104→            size="icon-xs"
105→            onClick={() => onDelete(task.id)}
106→            title="Delete task"
107→          >
108→            <Trash2 className="size-3" />
109→          </Button>
110→        </div>
111→      </div>
112→
113→      {editing ? (
114→        <div className="mt-2 space-y-2">
115→          <textarea
116→            className="w-full rounded border bg-transparent p-1.5 text-xs outline-none resize-none"
