node -e "
const WebSocket = require('ws');

const tasks = [
  ['Add message timestamps', 'Show relative timestamps (\"2m ago\") on each message, with hover to see the absolute time. Helps track conversation flow and understand timing between exchanges.', 'high'],
  ['Add markdown rendering for assistant messages', 'Claude outputs markdown (code blocks, headers, lists, bold/italic) but messages are currently rendered as plain text. Use a markdown renderer to properly display formatted content.', 'high'],
  ['Add search/filter messages', 'Long conversations are impossible to navigate. Add a Cmd+F style search bar to filter messages by content or tool name.', 'high'],
  ['Add syntax highlighting in tool call JSON', 'Control request cards show raw JSON in a plain code block. Add syntax highlighting and proper indentation to make tool approval decisions easier.', 'high'],
  ['Add streaming text display', 'Messages currently appear all at once after processing. Show assistant text as it streams in to make the UI feel more responsive and give earlier feedback.', 'high'],
  ['Add multi-pane / split view for agents', 'Currently you can only see one agent at a time. Add side-by-side or tabbed views to monitor multiple agents working in parallel.', 'medium'],
  ['Add copy message button on hover', 'No way to copy a message content. Add a small copy icon that appears on hover to copy the message text to clipboard.', 'medium'],
  ['Add keyboard shortcuts for common actions', 'Add keyboard shortcuts: Enter to send, Ctrl+1/2/3 to switch agents, keyboard approve/deny for tool calls, etc.', 'medium'],
  ['Add auto-scroll toggle with jump-to-bottom button', 'Auto-scroll can be annoying when reading history. Disable auto-scroll when user scrolls up, show a floating \"jump to bottom\" button, and re-enable when clicked.', 'medium'],
  ['Add message export (markdown/JSON)', 'Allow exporting a conversation as markdown or JSON for sharing, documentation, or archival purposes.', 'medium'],
  ['Add tool call result previews in condensed groups', 'Condensed tool groups show what tools were called but not the results. Show truncated output inline to give context without expanding.', 'low'],
  ['Add agent cost/duration summary card', 'The result message contains cost and duration data. Show a summary card at the top of each agent with total cost, duration, and turn count.', 'low'],
  ['Add connection status toast notifications', 'WebSocket reconnection happens silently. Show brief toast notifications when connection drops or restores to build user trust.', 'low'],
  ['Add empty state with quick-start instructions', 'When no agent is selected, the chat area is blank. Add a helpful empty state with instructions on how to get started.', 'low'],
  ['Add resizable sidebar', 'The sidebar width is fixed. Add a drag handle to resize so users can optimize their layout.', 'low'],
];

const ws = new WebSocket('ws://localhost:9900/browser');
let taskIndex = 0;
let ready = false;

ws.on('message', (data) => {
  const msg = JSON.parse(data.toString());
  if (msg.type === 'task_list') {
    if (!ready) {
      ready = true;
      sendNext();
    } else {
      sendNext();
    }
  }
});

function sendNext() {
  if (taskIndex >= tasks.length) {
    console.log('Done! Created all ' + tasks.length + ' tasks.');
    ws.close();
    return;
  }
  const [title, description, priority] = tasks[taskIndex];
  ws.send(JSON.stringify({
    type: 'create_task',
    title,
    description,
    priority,
  }));
  console.log('Created: ' + title);
  taskIndex++;
}

ws.on('error', (err) => {
  console.error('WebSocket error:', err.message);
  process.exit(1);
});
" 2>&1
